"""Exercise draft resident cores without installing or invoking a transport."""
import os
from pathlib import Path
import shlex
import subprocess
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[1]


class ReadinessResidentTests(unittest.TestCase):
    def test_packed_tss_checks_and_resident_revocation(self):
        with tempfile.TemporaryDirectory() as tmp:
            folder = Path(tmp)
            # Production identity must be generated by the reviewed integration.
            # This fixture identifies only the host simulation.
            (folder / "ko_build_id.h").write_text("#define KO_BUILD_ID_BYTES {0x5a}\n")
            executable = folder / "readiness-resident-test"
            compiler = shlex.split(os.environ.get("HOST_CC", "cc"))
            subprocess.run([*compiler, "-std=c11", "-Wall", "-Wextra", "-Werror",
                            "-I", str(folder), "-I", str(ROOT / "payloads/kernel-offset"),
                            str(ROOT / "tests/test_readiness_resident.c"), "-o", str(executable)], check=True)
            subprocess.run([str(executable)], check=True)


if __name__ == "__main__":
    unittest.main()
